import sys

def main():
    data = sys.stdin.read().split()
    N = int(data[0]); M = int(data[1])
    S = data[2]
    mod = 998244353
    size = 1 << N
    Sarr = [ord(ch) - 97 for ch in S]

    def row(mask):
        h = [0] * (N + 1)
        for i in range(1, N + 1):
            h[i] = h[i - 1] + ((mask >> (i - 1)) & 1)
        return h

    # Precompute transitions: for each mask, list of (next_mask, multiplicity)
    trans_cnt = []
    for mask in range(size):
        p = row(mask)
        cnt = [0] * size
        for c in range(26):
            q = [0] * (N + 1)
            for i in range(1, N + 1):
                best = p[i]
                if q[i - 1] > best:
                    best = q[i - 1]
                v = p[i - 1] + (1 if Sarr[i - 1] == c else 0)
                if v > best:
                    best = v
                q[i] = best
            nm = 0
            for i in range(1, N + 1):
                if q[i] > q[i - 1]:
                    nm |= 1 << (i - 1)
            cnt[nm] += 1
        trans_cnt.append([(nm, m) for nm, m in enumerate(cnt) if m])

    dp = [0] * size
    dp[0] = 1
    for _ in range(M):
        new = [0] * size
        for mask in range(size):
            c0 = dp[mask]
            if c0:
                for nm, m in trans_cnt[mask]:
                    new[nm] = (new[nm] + c0 * m) % mod
        dp = new

    ans = [0] * (N + 1)
    for mask in range(size):
        pc = bin(mask).count('1')
        ans[pc] = (ans[pc] + dp[mask]) % mod

    sys.stdout.write(' '.join(map(str, ans)) + '\n')

main()

