import sys
import numpy as np
from collections import deque

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    grid = data[1:1 + n]

    L = np.full((n, n), -1, dtype=np.int8)
    for i in range(n):
        row = grid[i]
        for j in range(n):
            ch = row[j]
            if ch != '-':
                L[i][j] = ord(ch) - 97

    dist = np.full((n, n), -1, dtype=np.int32)
    q = deque()
    for i in range(n):
        dist[i][i] = 0
        q.append((i, i))
    for i in range(n):
        for j in range(n):
            if i != j and L[i][j] >= 0:
                dist[i][j] = 1
                q.append((i, j))

    # pre[i][c]: array of u with edge u->i labeled c
    # suc[j][c]: array of v with edge j->v labeled c
    pre = [[None] * 26 for _ in range(n)]
    suc = [[None] * 26 for _ in range(n)]
    for i in range(n):
        col = L[:, i]
        for c in range(26):
            pre[i][c] = np.nonzero(col == c)[0]
    for j in range(n):
        row = L[j, :]
        for c in range(26):
            suc[j][c] = np.nonzero(row == c)[0]

    while q:
        i, j = q.popleft()
        d = dist[i][j]
        nd = d + 2
        for c in range(26):
            P = pre[i][c]
            if P.size == 0:
                continue
            S = suc[j][c]
            if S.size == 0:
                continue
            sub = dist[np.ix_(P, S)]
            mask = (sub == -1)
            if not mask.any():
                continue
            sub[mask] = nd
            dist[np.ix_(P, S)] = sub
            newidx = np.argwhere(mask)
            for r, s in newidx:
                q.append((int(P[r]), int(S[s])))

    out = []
    for i in range(n):
        out.append(' '.join(map(str, dist[i].tolist())))
    sys.stdout.write('\n'.join(out) + '\n')

main()

