import sys, math

def main():
    N = int(sys.stdin.readline())

    # d = x - y must satisfy d^3 <= N, so d <= N^(1/3) <= 10^6
    limit = int(round(N ** (1.0 / 3.0))) + 2
    while limit ** 3 > N:
        limit -= 1
    while (limit + 1) ** 3 <= N:
        limit += 1

    for d in range(1, limit + 1):
        if N % d != 0:
            continue
        m = N // d
        # 3y^2 + 3dy + d^2 = m  =>  y = (-3d + sqrt(12m - 3d^2)) / 6
        D = 12 * m - 3 * d * d
        if D < 0:
            continue
        s = math.isqrt(D)
        if s * s != D:
            continue
        num = s - 3 * d
        if num <= 0 or num % 6 != 0:
            continue
        y = num // 6
        x = y + d
        if y > 0 and x * x * x - y * y * y == N:
            print(x, y)
            return

    print(-1)

main()

