import sys

def main():
    data = sys.stdin.read().split()
    N = int(data[0])
    S = data[1] if len(data) > 1 else ""
    MOD = 998244353

    children = []
    stack = []
    roots = []
    for ch in S:
        if ch == '(':
            children.append([])
            stack.append(len(children) - 1)
        else:
            v = stack.pop()
            if stack:
                children[stack[-1]].append(v)
            else:
                roots.append(v)

    M = len(children)
    node_id = [0] * M
    id_map = {}
    for v in range(M - 1, -1, -1):
        key = tuple(sorted(node_id[c] for c in children[v]))
        nid = id_map.get(key)
        if nid is None:
            nid = len(id_map)
            id_map[key] = nid
        node_id[v] = nid

    fact = [1] * (M + 1)
    for i in range(1, M + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (M + 1)
    inv_fact[M] = pow(fact[M], MOD - 2, MOD)
    for i in range(M, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def contribution(lst):
        m = len(lst)
        if m <= 1:
            return 1
        ids = sorted(node_id[c] for c in lst)
        res = fact[m]
        i = 0
        while i < m:
            j = i + 1
            while j < m and ids[j] == ids[i]:
                j += 1
            res = res * inv_fact[j - i] % MOD
            i = j
        return res

    ans = contribution(roots)
    for v in range(M):
        if len(children[v]) > 1:
            ans = ans * contribution(children[v]) % MOD

    print(ans)

main()
